ProjectALife.DialogueShards["replies_who_1"] = {
{"WHO_ARE_YOU","reg=law",{"Deputy with the county, what's left of it","I'm with the sheriff's office, twelve years on the job","Trooper - state police, my post went quiet a week ago"}},
{"WHO_ARE_YOU","reg=swat",{"County tactical team, used to be eight of us"}},
{"WHO_ARE_YOU","reg=swat|st=careful,hostile",{"Police, that's all you need to know"}},
{"WHO_ARE_YOU","reg=swat|st=friendly,neutral",{"I'm on the response team, or I was","Police tactical unit, that's all you need"}},
{"WHO_ARE_YOU","reg=military,elite",{"National Guard, my unit's scattered all over this county","Private, United States Army, nobody's relieved me yet"}},
{"WHO_ARE_YOU","reg=military,elite|st=friendly,neutral",{"Just a soldier waiting on orders that don't come","A soldier, doing what soldiers do"}},
{"WHO_ARE_YOU","reg=civilian,family,worker,rescue",{"I'm just a person, I sold insurance in West Point","Nobody special, I used to teach second grade"}},
{"WHO_ARE_YOU","reg=civilian,family,worker,rescue|world=vehicle",{"I drove a delivery truck - bread, mostly"}},
{"WHO_ARE_YOU","reg=raider,outlaw,gang,club,crime,prison",{"Who's asking?","Nobody you want to know"},false,{[1]="GENERIC"}},
{"WHO_ARE_YOU","reg=raider,outlaw,gang,club,crime,prison|st=careful,hostile",{"The guy with the gun - that's who"}},
{"WHO_ARE_YOU","reg=civilian,family,worker,rescue|tmp=fresh|st=friendly,neutral",{"Who am I? Just- just somebody, okay? somebody trying to get through the day","N-nobody special... honest, I'm nobody, I used to have a regular life and a regular job and a regular lawn","Me? I'm- God, I haven't introduced myself to a stranger in so long, hi, hello, I'm a person, a plain old person","A neighbor, a friend, a mom, a dad, a guy who got up one morning and the world was gone!","Who the hell are YOU? sorry, sorry, rude, I'm just on edge, I'm nobody, I'm harmless","I'm someone who's really, really hoping you're not going to hurt me!","Just another survivor, there's a lot of us, we just don't see each other much","A regular person in a very irregular week... that's all you need to know","I'm a human being, okay? with a pulse, and ten fingers, and all my teeth, and nothing in my pockets","Me? I'm- I'm nobody, just a regular person, I used to work in an office","I'm a mess, mostly, a mess with a flashlight, who are you?","Just somebody who's trying very hard to stay alive, nice to meet you","I'm a person, with fears, and a bag of crackers, and you?"}},
{"WHO_ARE_YOU","reg=civilian,family,worker,rescue|tmp=seasoned|st=friendly,neutral",{"Someone who's still standing, that's about the whole of my resume","Same as you, I'd guess, we're both walking around, so we both got lucky","A local, been here all my life, never thought I'd have to explain myself in my own town","Not a threat, not a friend, not a problem, I'm just a face you'll forget by tomorrow","Somebody who's been through it and is too tired to put a fancy name on it","I keep to myself, you could call me a hermit, a loner, a lucky son of a gun","Depends who's asking, and what they plan to do with the answer","What does it matter? we're all the same now, just people trying not to die","Somebody who's seen better days, and worse ones, depends on the hour","A survivor, a cook, a good-for-nothing, a friend if you're lucky","I'm the guy you ask when you need a quiet place to sit","Nobody special, one more set of tired feet on the road"}},
{"WHO_ARE_YOU","reg=civilian,family,worker,rescue|st=friendly",{"I'm a friend, or I'd like to be, I haven't had a friend in a while, so, hi!","Huh, who am I... still working that out, honestly, but nice to meet you","Oh, hi! Nobody ever asks... I'm nobody special, just a regular person, you?"}},
{"WHO_ARE_YOU","reg=civilian,family,worker,rescue|st=careful",{"Who wants to know?!","Who's asking?","I could ask you the same, and I'd like an answer first","Someone you don't need to worry about -- and I'd like to keep it that way!","Nobody you need to worry about","I don't answer that for people I don't know","A person with a long memory and a short temper","Someone who's seen what people do","That's my business"},false,false,{[5]={{t="and I'd keep it that way",afterMs=3000}},[8]={{t="and doesn't plan to be next",afterMs=3000}}}},
{"WHO_ARE_YOU","role=civilian_man,civilian_woman|st=friendly,neutral",{"Just a regular person, I used to sell insurance, now I sell nothing, buy nothing, hide a lot"}},
{"WHO_ARE_YOU","role=civilian_loner|st=friendly,neutral",{"A hunter, a drifter, a man of few words, and fewer friends","A man who lives out there","Somebody who left town years ago... for good reasons..","Name's not important"},false,false,{[2]={{t="that's about all",afterMs=3500}},[4]={{t="I've answered to worse",afterMs=3200}}}},
{"WHO_ARE_YOU","role=family_man,family_woman|st=friendly,neutral",{"I'm a mother, I'm a father, I'm a husband, I'm a wife, that's who I am first, last, always","A father... a husband, a man trying to keep his family alive","I'm somebody's mom"},false,false,{[2]={{t="that's about all there is to me",afterMs=3500}},[3]={{t="that's the most important part",afterMs=3200}}}},
{"WHO_ARE_YOU","role=family_elder|st=friendly,neutral",{"An old woman, an old man, too old for this, too stubborn to quit","Just an old woman, dear","I'm somebody's grandmother, somebody's mother, somebody's wife"},false,false,{[2]={{t="an old woman who's seen a thing or two",afterMs=3500}},[3]={{t="and I'm tired",afterMs=3200}}}},
{"WHO_ARE_YOU","role=family_youth|st=friendly,neutral",{"Just a kid, I guess, or I was, I'm not sure what I am anymore","I'm, uh, just a kid","I'm nobody, I mean, nobody important...","I was gonna start at UK in the fall - so, a freshman? Of nothing, I guess"},false,false,{[2]={{t="I mean, I'm seventeen, so, an adult-ish",afterMs=3200}}}},
{"WHO_ARE_YOU","role=worker|st=friendly,neutral",{"A working stiff, a regular Joe, somebody who showed up on time and went home tired","Just a guy who fixes things","Foreman, welder, mechanic, pick one"},false,false,{[2]={{t="or fixed things",afterMs=3500},{t="before everything broke",afterMs=3000}},[3]={{t="I've been all three",afterMs=3200}}}},
{"WHO_ARE_YOU","role=rescue_medical|st=friendly,neutral",{"A nurse, a doctor, a medic, a person who knows how to help, if you'll let me","A nurse, a medic, a pair of steady hands in a very unsteady world","I'm the one you want to find when you're hurt, and the last one you want to meet when you're not"}},
{"WHO_ARE_YOU","role=rescue_clergy|st=friendly,neutral",{"I'm the pastor... deacon, really- I look after folks, or I did, or I'm trying to","A servant, a shepherd, a man who prays","I'm the pastor","A servant of the Lord, these days mostly a digger of graves, God forgive me for saying it"},false,false,{[2]={{t="and cooks, when there's something to cook",afterMs=3500}},[3]={{t="the only one left, I think",afterMs=3200}}}},
{"WHO_ARE_YOU","role=rescue_firefighter|st=friendly,neutral",{"Firefighter, volunteer, I put out fires, now I put out whatever's burning today","Firefighter","I put out fires","Muldraugh volunteer fire, came out on a call Friday night and never got home"},false,false,{[2]={{t="volunteer, mostly",afterMs=3500},{t="and still on call",afterMs=3000}},[3]={{t="there are a lot to put out",afterMs=3200}}}},
{"WHO_ARE_YOU","role=militia|st=friendly,neutral",{"Local boy, rifleman, part of the watch, trying to keep my corner of the county in one piece","Local boy","Militia"},false,false,{[2]={{t="with a rifle and a bad attitude",afterMs=3500},{t="but a good heart",afterMs=3000}},[3]={{t="don't let the word scare you, it just means \"neighbors with rifles\"",afterMs=3200}}}},
{"WHO_ARE_YOU","reg=civilian,family,worker,rescue|tmp=fresh|st=friendly,neutral|mood=fear",{"Please don't hurt me, please, I'm nobody, I'm a nobody, I have nothing","Who are YOU? I'm sorry, sorry, I mean, I'm- I'm just a person, a scared one","Don't look at me like that, I'm nobody, honest- I'm just trying to live"}},
{"WHO_ARE_YOU","reg=civilian,family,worker,rescue|tmp=seasoned|st=friendly,neutral|mood=grim",{"Just another face in a crowd of ghosts","Someone who's seen too much and said too little","A survivor, a witness, a pallbearer, a cook, a bit of everything"}},
{"WHO_ARE_YOU","reg=civilian,family,worker,rescue|st=friendly,neutral|mood=sad",{"I was somebody's husband, somebody's father, somebody's son, now I'm just myself","I used to be a wife, a mother, a sister, now I'm what's left.."}},
{"WHO_ARE_YOU","reg=civilian,family,worker,rescue|st=friendly,neutral|mood=angry",{"Who the hell wants to know? why? are you taking names for the next list?","I'm the person who's had enough, that's who I am"}},
{"WHO_ARE_YOU","reg=civilian,family,worker,rescue|st=friendly|mood=warm",{"A friend, I hope, a new one, a good one, nice to meet you","Someone who's glad you're here, truly, I mean that"}},
{"WHO_ARE_YOU","reg=civilian,family,worker,rescue|st=friendly,neutral|mood=funny",{"I'm the guy who's always last in the buffet line... and first in the escape plan, ha","Just your friendly neighborhood nobody, ha, how about you?"}},
{"WHO_ARE_YOU","reg=civilian,family,worker,rescue|st=careful|mood=fear",{"W-who I am's none of your damn business","You first, then maybe I'll tell you"}},
{"WHO_ARE_YOU","role=rescue_medical|st=careful",{"I'm a nurse, and I don't owe you my name!"}},
{"WHO_ARE_YOU","reg=civilian,family,worker,rescue|st=friendly,neutral|rep=good,best",{"You don't remember me? I'm the one you helped, I owe you","I'm a friend, a friend of a friend, and a fan of yours, if I'm being honest","I'm someone who's glad to know you, and I'll say it again if you like","Just a survivor, like you, but not half as brave","I've heard so much about you, I feel like I already know you","Someone who owes you a favor, whether you know it or not","A friend, I hope, I'd like to be a friend","Ordinary, like most of us, glad to be talking with you","A person you can trust, I hope you'll agree","I'm the one who tells everyone how you helped, I'm your biggest admirer","Nobody special, but glad to be here, glad to meet you again","Someone who's still standing, and glad you are, too","Your neighbor, your friend, your ally, pick one","I'm the person who saved you a seat, and a biscuit!!","A friend of the family, you're family now","Call me a believer, in you, in people like you","Just somebody who appreciates what you did, that's all!","I'm part of the folks you helped, I never got to say thank you","A fellow traveler, a friend on the road","A survivor with a soft spot for good people","Someone who's rooting for you, always","Just another face in the crowd who knows your name!","I'm the one with the coffee, if there were any coffee","A pair of ears, a shoulder, a friend","I'm someone you can lean on, if you need to","One of the lucky ones, who happens to know you","I'm the one who owes you a drink, a meal, a prayer","Just a friend, that's all","Just glad to be here, glad to be alive, glad you are, too","Somebody who's grateful, really grateful"}},
{"WHO_ARE_YOU","reg=civilian,family,worker,rescue|st=careful,neutral|rep=bad,worst",{"None of your business, and I know exactly who YOU are","I'm someone who remembers what you did","A person you don't want to cross","Someone who's got eyes on you","I'm NOT telling you anything","I'm the one who'll make you regret it!","Someone who isn't afraid of you","A survivor, no thanks to you","The one you hurt, remember?","Someone you should leave alone!!","A neighbor, a witness, a problem for you","I'm the person who's heard everything about you","Nobody you need to know","A person who doesn't owe you an introduction","Your worst nightmare, hopefully","Someone with a long memory","The one who'll tell everybody what you did!","A stranger who knows too much","A survivor, with a grudge","A person you shouldn't have met","Somebody who warns people about you","I'm the one with a long list, and your name's on it","A voice in the crowd, saying \"not him\"","The person who's about to say goodbye","Someone who prays you go away","A stubborn old fool, who doesn't forget","Just someone who's NOT impressed!!","The one holding the shotgun, metaphorically!","A resident, a taxpayer, a headache for you","The one who says no!","Someone who's seen your type before"}},
{"WHO_ARE_YOU","reg=civilian,family,worker,rescue|st=friendly,neutral|day=0,99999|fact=recent_zombie_contact",{"Later, later, introductions later, there are THINGS out there","Who cares, who cares, get down, they're coming!!","Just a person, a scared one, that's all","Not now, not now, move, go, go","Nobody... nobody, shush, shush, please!","A survivor, like you, now be quiet, they'll hear us","I'll tell you when we're safe, if we're ever safe","Does it matter? run!"}},
{"WHO_ARE_YOU","reg=civilian,family,worker,rescue|st=friendly,neutral|day=0,99999|fact=player_armed",{"Just a regular person, who's very glad you're armed","Someone who'd like to stay on your good side","A friend, I hope, a friend of the person with the gun","Nobody dangerous... as you can see, unlike some people...","Why, who are you, and what's with the hardware?"}},
{"WHO_ARE_YOU","role=civilian_loner|st=careful",{"Nobody!"}},
{"WHO_ARE_YOU","role=family_youth|st=careful",{"I don't tell my name to strangers, my mom said so"}},
{"WHO_ARE_YOU","role=rescue_clergy|st=careful",{"A priest"}},
{"WHO_ARE_YOU","reg=raider|st=neutral,careful",{"Who am I? Heh -- I'm the reason you keep checking behind you","Somebody you do NOT want to owe, that clear enough?","Nobody, {g:pal|lady}, nobody at all, and you'd be smart to leave it that way","Who the hell are YOU? You walked up on me, remember?","I'm the guy who decides if this talk ends nice or not","Raider, if you need a word for it -- don't look so shocked, it's not a secret","Funny, people usually ask that AFTER, not before","I'm the one eating while everybody else starves, how's that for an answer","Call me the toll, everybody pays the toll sooner or later","Who I am isn't your problem, what I want from you is","Aww, he wants a name... guess, then, go on, take a guess","I'm what's left when the rules go away, and I like it a lot","Somebody with a lot more to lose than you've got, so watch your mouth","Someone you'll want to remember so you can tell your friends -- if you got any"}},
{"WHO_ARE_YOU","reg=raider|st=hostile",{"Your worst day, dumbass, and it's gonna get longer if you keep talking","WHO AM I?! Who the fuck are YOU?!","The last thing you ever ask anybody, friend","Ask me again, go ahead, I'll answer with my fist","Nobody you're gonna get to tell anyone about","Somebody who's bored, and you're the only thing moving around here"}},
{"WHO_ARE_YOU","reg=raider|st=friendly",{"Me? Just a guy trying to keep breathing, same as you, relax","Friend or enemy, we'll see -- right now I'm just curious about you","Easy, I'm one of the ones that talks first, that's a good sign for you"}},
{"WHO_ARE_YOU","role=raider_boss,gang_boss,biker_boss|st=neutral,careful",{"I run this, and that's all you need to know","I'm the man whose people you just walked in on, so pick your next words real careful","Somebody people answer to -- now you answer me, who are you?"}},
{"WHO_ARE_YOU","reg=gang|st=neutral,careful",{"I'm somebody's blood, somebody's soldier, that's it, that's all of it","We don't do introductions with strangers, who sent you?","I roll with people you don't wanna meet, leave it there","Who's asking, and what's it to you?","I'm the guy standing between you and my block, you like that?","This is OUR turf, you tell me who you are","My name's in a lot of mouths around here, just not yours"}},
{"WHO_ARE_YOU","reg=gang|st=hostile",{"I'm your problem, right now, today","Nobody you wanna know, so quit asking","You wanna know who I am? Keep walking at me, you'll find out"}},
{"WHO_ARE_YOU","reg=gang|st=friendly",{"Just a guy from around here, you're good, you're good, relax","Name's whatever you wanna call me, we cool? We cool"}},
{"WHO_ARE_YOU","role=gang_boss|st=neutral,careful",{"The one making the calls on this block, and not your business past that","You're asking the shot caller who he is? Think about that for a second"}},
{"WHO_ARE_YOU","reg=club|st=neutral,careful",{"The patch says it, read it or don't","Brother of the club, that's who -- and you are?","I ride with people who'd bury you quiet, nice to meet you","Member in good standing, and don't ask me what the standing means","Same as I was before the dead got up, club first, always","Somebody who's got brothers -- you got brothers? Didn't think so"}},
{"WHO_ARE_YOU","reg=club|st=hostile",{"The guy about to take your seat at the funeral, anything else?","Just a man with nothing left to lose, wanna test that?"}},
{"WHO_ARE_YOU","reg=club|st=friendly",{"Easy, friend, just a club man trying to keep my people fed","Another poor bastard in a bad stretch, and you look like one too"}},
{"WHO_ARE_YOU","role=biker_boss|st=neutral,careful",{"The man who answers for everybody else, so you answer for yourself","President, that mean something to you? Didn't think so"}},
{"WHO_ARE_YOU","reg=crime|st=neutral,careful",{"An associate -- of whom, I'd rather not say in front of strangers","Nobody important, which is how I like it, and you?","Someone who handles business, you're not business, yet","I work for people who'd rather you didn't ask me that"}},
{"WHO_ARE_YOU","reg=crime|st=hostile",{"You don't wanna know who I work for, believe me, just walk away"}},
{"WHO_ARE_YOU","reg=crime|st=friendly",{"A friend if you're a friend, a problem if you're a problem, which is it?"}},
{"WHO_ARE_YOU","reg=prison|st=neutral,careful",{"Me? I don't-- I'm nobody, I never was, just let me be","Don't look at me like that, I ain't going back, never, who are YOU?","They took my name at intake, I'm still waiting to get it back","Just a man walking out of a bad place, that's all","I'm what happens when you lock a man up and forget the key"}},
{"WHO_ARE_YOU","reg=prison|st=hostile",{"Somebody who's done his time, and I'm not going BACK, you get that?!","Back off! Just back off, I did my time, I did my ti-- back off!"}},
{"WHO_ARE_YOU","reg=prison|st=friendly",{"Aw hell, just a guy who got out when it all fell apart, don't be scared of me"}},
{"WHO_ARE_YOU","reg=outlaw|st=neutral,careful",{"Nobody you've heard of, better for both of us","Outlaw, if you need a word for it -- didn't pick it, it picked me","A man on his own working it out as he goes, same as you","A name doesn't feed anybody, so I quit carrying mine around","Just passing through, same as you from the look of it","Who I used to be doesn't count anymore"}},
{"WHO_ARE_YOU","reg=outlaw|st=hostile",{"Who am I? The wrong guy to be pointing that at"}},
{"WHO_ARE_YOU","reg=outlaw|st=friendly",{"Name's not important, I'm a decent sort when nobody's shooting"}},
{"WHO_ARE_YOU","role=deserter|st=neutral,careful",{"Nobody, I used to be somebody in a uniform, don't ask me which one","Just a man who walked away, please leave it there","I was a private-- no, I'm just a man now, is that okay?"}},
{"WHO_ARE_YOU","reg=law|st=neutral,careful",{"Deputy with the county, and you are?","Give me your name first, then I'll give you mine","Sheriff's office -- keep your hands where I can see them, please","Law enforcement, hands visible please","I'm an officer, that's all I'll say until I know who you are","County, still on duty, still trying"}},
{"WHO_ARE_YOU","reg=law|st=hostile",{"I'm the law, so turn around slow, hands out, I won't ask twice","I'm the one asking, you're the one answering -- name, NOW"}},
{"WHO_ARE_YOU","reg=law|st=friendly",{"Deputy, and it's good to see somebody upright, what can I do for you?","Law enforcement -- relax, friend, I'm not looking to arrest anybody today"}},
{"WHO_ARE_YOU","role=law_sheriff|st=neutral,careful",{"Sheriff of this county, what's left of it, state your business","Sheriff, which means I'm the one asking the questions"}},
{"WHO_ARE_YOU","role=law_trooper|st=neutral,careful",{"Kentucky State Police, trooper, and I'd like your name before you take another step","Trooper, state police -- who are you, please?"}},
{"WHO_ARE_YOU","role=law_sergeant|st=neutral,careful",{"Sergeant, that's all you need, and more than you're getting","Sergeant, county patrol, who are you and what are you doing here?"}},
{"WHO_ARE_YOU","role=law_corrections|st=neutral,careful",{"Corrections, used to be a prison guard, now I'm a guy with keys to nothing","Guard, twelve years on the block, now I'm on this block, funny, huh"}},
{"WHO_ARE_YOU","reg=swat|st=neutral,careful",{"Tactical, that's all you get","We're a unit, the unit isn't important, who are you?","Authorized personnel -- identify yourself"}},
{"WHO_ARE_YOU","reg=swat|st=hostile",{"Identify yourself, NOW, hands where we can see them!"}},
{"WHO_ARE_YOU","reg=military|st=neutral,careful",{"Soldier, United States Army, who are you?","Specialist, and I need a name from you before I say any more","Army, move along unless you've got business","Quarantine detail, name and business, now"}},
{"WHO_ARE_YOU","reg=military|st=hostile",{"Identify yourself or we will treat you as hostile!"}},
{"WHO_ARE_YOU","reg=military|st=friendly",{"Army -- you're safe with me, glad to see you in one piece"}},
{"WHO_ARE_YOU","role=soldier_nco|st=neutral,careful",{"Sergeant, and you'll address me as such -- and you are?","Staff Sergeant, I'd tell you the rest but I'd want to be sure of you first"}},
{"WHO_ARE_YOU","role=soldier_green|st=neutral,careful",{"Uh, Private... Private-- I'm a soldier, I'm in the Army, are you, uh, a civilian?","I'm just a guy in a uniform, I wasn't supposed to be here, please don't ask"}},
{"WHO_ARE_YOU","reg=elite|st=neutral,careful",{"No name, no unit, move on","You don't need to know who I am, I already know enough about you","A professional, leave it there"}},
{"WHO_ARE_YOU","role=elite_delta|st=neutral,careful",{"Nobody you can name, keep it that way"}},
{"WHO_ARE_YOU","role=mercenary|st=neutral,careful",{"I used to work security, now I watch these folks, who are you?","Hired help, now you"}},
{"WHO_ARE_YOU","role=militia|st=neutral,careful",{"Neighbor, township militia, we keep our people safe and strangers honest, who are you?","Local, rifleman, we watch this area -- say who you are","Just a man who got tired of waiting for the Army to show up"}},
{"WHO_ARE_YOU","role=militia|st=hostile",{"Militia, and we don't like strangers, name, quick!"}},
{"WHO_ARE_YOU","role=militia|st=friendly",{"Local fella with a rifle and a lot of scared neighbors, come on in, say hi"}},
{"WHO_ARE_YOU","reg=civilian,family,worker,rescue|tmp=seasoned|st=careful,neutral",{"Someone who doesn't owe you an explanation","Who's asking, and why?"}},
{"WHO_ARE_YOU","reg=family|st=friendly,neutral",{"Just an old woman who's seen a lot, dear, sit down and I'll tell you"}},
{"WHO_ARE_YOU","reg=law,swat|st=friendly,neutral",{"Law enforcement. You can talk to me, you don't have to stand there guessing"}},
{"WHO_ARE_YOU","reg=law,swat|st=careful,neutral",{"Someone who'd like your name first"}},
{"WHO_ARE_YOU","reg=military,elite|st=careful,neutral",{"I'm the one with the weapon, who are you?"}},
{"WHO_ARE_YOU","reg=outlaw,raider,gang,club,crime,prison|st=friendly,neutral",{"Heh, I'm the guy your mother warned you about","Who am I? Whoever you need me to be, for a price"}},
{"WHO_ARE_YOU","reg=outlaw,raider,gang,club,crime,prison|st=careful,hostile",{"Your worst mistake, kid"}},
{"WHO_ARE_YOU","reg=civilian,family,worker,rescue|st=careful,neutral|rep=bad",{"Who am I? Somebody who's heard what you did, that's enough for now","Let's trade, you tell me what they say about you is wrong, then I tell you my name","Why, so you can find me later? Hm, no, not today"}},
{"WHO_ARE_YOU","reg=civilian,family,worker,rescue|st=friendly,neutral|rep=good",{"Me? Nobody, really, but you, I hear you're somebody","Just a person who's real glad you're the one that asked"}},
{"WHO_ARE_YOU","reg=law,swat|st=careful,neutral|rep=bad",{"Somebody with a notebook and your name written in it, that's who"}},
{"WHO_ARE_YOU","reg=law,swat|st=friendly,neutral|rep=good",{"Somebody who read a report about you, a good one, don't ask me to repeat it, I'll blush"}},
{"WHO_ARE_YOU","reg=military,elite|st=careful,neutral|rep=bad",{"Somebody who read your file, short file, not a nice one"}},
{"WHO_ARE_YOU","reg=military,elite|st=friendly,neutral|rep=good",{"A friend, as long as you keep being what the net says you are"}},
{"WHO_ARE_YOU","reg=outlaw,raider,gang,club,crime,prison|st=careful,neutral|rep=bad",{"Somebody who knows what you are, same as you know me, so let's leave it"}},
{"WHO_ARE_YOU","reg=outlaw,raider,gang,club,crime,prison|st=neutral,careful,hostile|rep=worst",{"A fan, heh, well, not a fan, a fan from behind a wall"}},
{"WHO_ARE_YOU","reg=civilian,family|tmp=fresh|st=friendly,neutral",{"Nobody special, I rang up groceries in Riverside - please, I'm nobody, I'm just trying to get home"}},
{"WHO_ARE_YOU","role=civilian_woman,family_woman|st=friendly,neutral",{"I'm a mom, that's it, that's all I am right now - somebody's mom who needs to get back to her"}},
{"WHO_ARE_YOU","role=family_man,civilian_man|st=friendly,neutral",{"Just a dad from March Ridge with a station wagon full of kids and no gas - that's who"}},
{"WHO_ARE_YOU","role=family_elder|st=friendly,neutral|world=road",{"I'm the one that's lived in that yellow house since before they paved the road - who are you?"},false,{[1]="GENERIC"}},
{"WHO_ARE_YOU","reg=civilian,family,worker|tmp=seasoned,veteran|st=friendly,neutral",{"Used to be somebody with a mortgage, now I'm somebody with a crowbar","Somebody who's made it this far, that's the only kind of resume left"}},
{"WHO_ARE_YOU","role=militia|st=friendly,neutral|world=road",{"Neighborhood watch, with better rifles, we keep an eye on this end of the road"}},
{"WHO_ARE_YOU","reg=worker|st=friendly,neutral|world=road",{"Mechanic for the county road department, or I was, now I fix whatever rolls in"}},
{"WHO_ARE_YOU","role=rescue_medical|st=friendly,neutral|world=vehicle",{"EMT, the ambulance is in a ditch off 31W, but I'm still an EMT"}},
{"WHO_ARE_YOU","reg=civilian,family|tmp=fresh|st=careful",{"I'm, just, why? Who's asking? Are you with those men from the gas station?"},false,{[1]="GENERIC"}},
